const input = ($json && typeof $json === 'object') ? $json : {};
const src = (input.body && typeof input.body === 'object' && !Array.isArray(input.body))
  ? input.body
  : input;
const headers = (input.headers && typeof input.headers === 'object') ? input.headers : {};

const text = (v, max = 4000) => {
  if (v === undefined || v === null) return null;
  return String(v)
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
    .trim()
    .slice(0, max);
};

const parseObject = (v) => {
  if (v && typeof v === 'object' && !Array.isArray(v)) return v;
  if (typeof v !== 'string' || !v.trim()) return {};
  try {
    const p = JSON.parse(v);
    return (p && typeof p === 'object' && !Array.isArray(p)) ? p : {};
  } catch {
    return {};
  }
};

const lowerHeader = (name) => {
  const k = Object.keys(headers).find((key) => key.toLowerCase() === name.toLowerCase());
  return k ? headers[k] : null;
};

const boolVar = (value, defaultValue) => {
  if (value === undefined || value === null || value === '') return defaultValue;
  if (typeof value === 'boolean') return value;
  return ['1','true','yes','on'].includes(String(value).toLowerCase());
};

const intVar = (value, defaultValue) => {
  const n = Number.parseInt(String(value ?? ''), 10);
  return Number.isFinite(n) && n > 0 ? n : defaultValue;
};

const hash32 = (str) => {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
};

const executionId = (() => {
  try { return String($execution?.id || ''); } catch { return ''; }
})();
const claimToken = executionId || `exec-${Date.now()}-${Math.random().toString(36).slice(2, 12)}`;

const nestedMessage = (src.message && typeof src.message === 'object' && !Array.isArray(src.message))
  ? src.message : {};
const toolCallList = Array.isArray(nestedMessage.toolCallList) ? nestedMessage.toolCallList : [];
const firstToolCall = toolCallList[0] || nestedMessage.toolCall || src.toolCall || src.tool || {};
const functionBlock = parseObject(firstToolCall.function || {});

const provider = text(
  src.provider ||
  nestedMessage.provider ||
  lowerHeader('x-voice-provider') ||
  'unknown',
  100
)?.toLowerCase() || 'unknown';

const requestIdSupplied = text(
  src.requestId ||
  src.request_id ||
  nestedMessage.requestId ||
  lowerHeader('x-request-id'),
  200
);

const callId = text(
  src.callId ||
  src.call_id ||
  src.call?.id ||
  nestedMessage.callId ||
  nestedMessage.call_id ||
  nestedMessage.call?.id ||
  null,
  200
);

const sessionId = text(
  src.sessionId ||
  src.session_id ||
  src.conversationId ||
  src.conversation_id ||
  nestedMessage.sessionId ||
  nestedMessage.conversationId ||
  src.call?.sessionId ||
  src.call?.conversationId ||
  callId ||
  null,
  200
);

const toolCallId = text(
  src.toolCallId ||
  src.tool_call_id ||
  src.tool?.id ||
  src.toolCall?.id ||
  nestedMessage.toolCallId ||
  nestedMessage.tool_call_id ||
  firstToolCall.id ||
  null,
  200
);

const rawTool = text(
  src.toolName ||
  src.tool_name ||
  src.tool?.name ||
  src.toolCall?.name ||
  nestedMessage.toolName ||
  nestedMessage.tool_call?.name ||
  functionBlock.name ||
  firstToolCall.name ||
  null,
  100
);
const toolName = rawTool ? rawTool.toLowerCase() : null;

const argsRaw =
  src.arguments ??
  src.args ??
  src.tool?.arguments ??
  src.toolCall?.arguments ??
  nestedMessage.arguments ??
  nestedMessage.toolCall?.arguments ??
  functionBlock.arguments ??
  firstToolCall.arguments ??
  {};
const args = parseObject(argsRaw);

const customerRaw =
  (src.customer && typeof src.customer === 'object' ? src.customer : null) ||
  (src.call?.customer && typeof src.call.customer === 'object' ? src.call.customer : null) ||
  (nestedMessage.customer && typeof nestedMessage.customer === 'object' ? nestedMessage.customer : null) ||
  {};

const customer = {
  customerId: text(customerRaw.customerId || customerRaw.id, 200),
  name: text(customerRaw.name || customerRaw.fullName, 200),
  phone: text(customerRaw.phone || customerRaw.phoneNumber, 100),
  email: text(customerRaw.email || customerRaw.emailAddress, 254)
};
if (customer.email) customer.email = customer.email.toLowerCase();

const message = text(
  typeof src.message === 'string' ? src.message :
  src.transcript ||
  src.userMessage ||
  src.customerMessage ||
  nestedMessage.transcript ||
  nestedMessage.userMessage ||
  nestedMessage.content ||
  args.issue ||
  '',
  4000
) || '';

const suppliedTimestamp = text(
  src.timestamp ||
  src.timestampUtc ||
  src.createdAt ||
  nestedMessage.timestamp ||
  null,
  100
);
const parsedTs = suppliedTimestamp ? Date.parse(suppliedTimestamp) : NaN;
const timestampSupplied = !!suppliedTimestamp;
const timestampValid = !timestampSupplied || !Number.isNaN(parsedTs);
const timestamp = !timestampSupplied
  ? new Date().toISOString()
  : (timestampValid ? new Date(parsedTs).toISOString() : new Date().toISOString());

const intentMap = {
  faq: 'faq',
  general_question: 'faq',
  knowledge_base_question: 'faq',
  knowledge_base: 'faq',
  get_faq: 'faq',
  get_order_status: 'get_order_status',
  order_status: 'get_order_status',
  book_appointment: 'book_appointment',
  create_support_ticket: 'create_support_ticket',
  support_ticket: 'create_support_ticket',
  escalate_to_human: 'escalate_to_human',
  human_escalation: 'escalate_to_human'
};
const intent = intentMap[toolName] || 'unknown';

const argumentsSafe = {
  orderId: text(args.orderId || args.order_id, 100),
  preferredDate: text(args.preferredDate || args.preferred_date, 50),
  preferredTime: text(args.preferredTime || args.preferred_time, 50),
  timezone: text(args.timezone || args.timeZone, 100),
  appointmentType: text(args.appointmentType || args.appointment_type, 200),
  issue: text(args.issue || args.description, 4000),
  category: text(args.category, 100),
  priority: text(args.priority, 50)
};

const trustedContext = parseObject(
  src.trustedContext ||
  src.securityContext ||
  nestedMessage.trustedContext ||
  {}
);

const verificationStatus = text(
  trustedContext.customerVerificationStatus ||
  trustedContext.verificationStatus ||
  null,
  50
)?.toLowerCase() || null;

const verificationReference = text(
  trustedContext.verificationReference ||
  trustedContext.reference ||
  null,
  200
);

const verificationSignature = text(
  trustedContext.signature ||
  trustedContext.hmac ||
  lowerHeader('x-verification-signature') ||
  null,
  500
)?.toLowerCase() || null;

const verificationTimestamp = text(
  trustedContext.verificationTimestamp ||
  trustedContext.timestamp ||
  trustedContext.verifiedAt ||
  trustedContext.signedAt ||
  lowerHeader('x-verification-timestamp') ||
  null,
  100
);

const verificationTimestampMs = verificationTimestamp ? Date.parse(verificationTimestamp) : NaN;
const verificationTimestampValid = !!verificationTimestamp && !Number.isNaN(verificationTimestampMs);
const verificationMaxAgeSeconds = intVar($vars.VERIFICATION_MAX_AGE_SECONDS, 300);
const verificationAgeSeconds = verificationTimestampValid
  ? Math.floor((Date.now() - verificationTimestampMs) / 1000)
  : null;
const verificationFresh =
  verificationTimestampValid &&
  verificationAgeSeconds >= 0 &&
  verificationAgeSeconds <= verificationMaxAgeSeconds;

const requireSignedVerification = true;

const suppliedIdempotencyKey = text(
  src.idempotencyKey ||
  src.idempotency_key ||
  lowerHeader('x-idempotency-key') ||
  null,
  300
);
const bodyIdempotencyKey = text(src.idempotencyKey || src.idempotency_key || null, 300);
const headerIdempotencyKey = text(lowerHeader('x-idempotency-key') || null, 300);
const idempotencyKeyConflict = !!(bodyIdempotencyKey && headerIdempotencyKey && bodyIdempotencyKey !== headerIdempotencyKey);

const requestIdGenerated = !requestIdSupplied;
const requestId = requestIdSupplied ||
  `generated-${Date.now()}-${hash32(`${provider}|${sessionId}|${callId}|${toolName}|${message}`).toString(16)}`;

const identityPresent = !!(customer.customerId || customer.name || customer.phone || customer.email);
const identityStrongEnough = !!(customer.phone || customer.email);


const requiredIntegrationConfig = [];
const hasVar = (name) => {
  try {
    return !!String($vars[name] ?? '').trim();
  } catch { return false; }
};

if (['faq'].includes(intent)) {
  if (!hasVar('SUPPORT_KB_BASE_URL')) requiredIntegrationConfig.push('SUPPORT_KB_BASE_URL');
  if (!hasVar('SUPPORT_LLM_BASE_URL')) requiredIntegrationConfig.push('SUPPORT_LLM_BASE_URL');
  if (!hasVar('SUPPORT_LLM_MODEL')) requiredIntegrationConfig.push('SUPPORT_LLM_MODEL');
}
if (intent === 'get_order_status') {
  if (!hasVar('SUPPORT_ORDER_BASE_URL')) requiredIntegrationConfig.push('SUPPORT_ORDER_BASE_URL');
  if (!hasVar('VOICE_VERIFICATION_HMAC_SECRET')) requiredIntegrationConfig.push('VOICE_VERIFICATION_HMAC_SECRET');
}
if (intent === 'book_appointment' && !hasVar('SUPPORT_CALENDAR_BASE_URL')) {
  requiredIntegrationConfig.push('SUPPORT_CALENDAR_BASE_URL');
}
if (intent === 'create_support_ticket' && !hasVar('SUPPORT_TICKET_BASE_URL')) {
  requiredIntegrationConfig.push('SUPPORT_TICKET_BASE_URL');
}
if (intent === 'escalate_to_human' && !hasVar('SUPPORT_ESCALATION_BASE_URL')) {
  requiredIntegrationConfig.push('SUPPORT_ESCALATION_BASE_URL');
}

const validationIssues = [];
if (requiredIntegrationConfig.length) validationIssues.push('integration configuration');
if (!sessionId) validationIssues.push('sessionId');
if (!toolName) validationIssues.push('toolName');
if (timestampSupplied && !timestampValid) validationIssues.push('timestamp invalid');
if (timestampValid && timestampSupplied) {
  const ageSeconds = (Date.now() - parsedTs) / 1000;
  if (ageSeconds > 900) validationIssues.push('timestamp too_old');
  if (ageSeconds < -120) validationIssues.push('timestamp in_future');
}
if (idempotencyKeyConflict) validationIssues.push('idempotency key conflict');
const sideEffectingIntent = ['book_appointment','create_support_ticket','escalate_to_human'].includes(intent);
const stableRequestIdentityAvailable =
  !!suppliedIdempotencyKey ||
  !!(provider && callId && toolCallId);
const safeStableRequestIdentityAvailable =
  !!suppliedIdempotencyKey ||
  (sideEffectingIntent
    ? !!(provider && callId && toolCallId)
    : !!(provider && (
        (callId && toolCallId) ||
        toolCallId ||
        requestIdSupplied
      )));
if (!safeStableRequestIdentityAvailable) validationIssues.push('idempotency key or stable request identity');

if (['faq','create_support_ticket','escalate_to_human'].includes(intent) && !message) {
  validationIssues.push('message');
}
if (['get_order_status','book_appointment','create_support_ticket','escalate_to_human'].includes(intent) && !identityPresent) {
  validationIssues.push('customer identity');
}
if (intent === 'get_order_status') {
  if (!argumentsSafe.orderId) validationIssues.push('arguments.orderId');
  if (!identityStrongEnough) validationIssues.push('customer phone or email');
}
if (intent === 'book_appointment') {
  if (!argumentsSafe.preferredDate) validationIssues.push('arguments.preferredDate');
  if (!argumentsSafe.preferredTime) validationIssues.push('arguments.preferredTime');
  if (!argumentsSafe.timezone) validationIssues.push('arguments.timezone');
}
if (intent === 'create_support_ticket' && !(argumentsSafe.issue || message)) {
  validationIssues.push('issue or message');
}
if (intent === 'escalate_to_human' && !(argumentsSafe.issue || message)) {
  validationIssues.push('reason or message');
}

const verificationPayload = JSON.stringify({
  version: 'support-verification-v1',
  provider,
  sessionId: sessionId || '',
  callId: callId || '',
  toolCallId: toolCallId || '',
  intent,
  verificationReference: verificationReference || '',
  verificationTimestamp: verificationTimestamp || '',
  verificationStatus: verificationStatus || '',
  customerId: customer.customerId || '',
  customerName: customer.name || '',
  customerPhone: customer.phone || '',
  customerEmail: customer.email || '',
  protectedResourceId: intent === 'get_order_status' ? (argumentsSafe.orderId || '') : '',
});

const fingerprintSource = JSON.stringify({
  version: 'support-request-fingerprint-v2',
  provider,
  intent,
  channel: text(src.channel || nestedMessage.channel || 'voice', 50) || 'voice',
  customer,
  message,
  arguments: argumentsSafe
});

return [{
  json: {
    schemaVersion: '1.0',
    provider,
    normalizationAdapter: toolCallList.length
      ? 'tool-call-envelope'
      : (nestedMessage && Object.keys(nestedMessage).length ? 'nested-provider-envelope' : 'canonical-generic'),
    requestId,
    requestIdSupplied: !!requestIdSupplied,
    requestIdGenerated,
    sessionId,
    callId,
    toolCallId,
    timestamp,
    channel: text(src.channel || nestedMessage.channel || 'voice', 50) || 'voice',
    customer,
    trustedVerification: {
      status: verificationStatus,
      reference: verificationReference,
      signature: verificationSignature,
      signaturePresent: !!verificationSignature,
      timestamp: verificationTimestamp,
      state: 'pending'
    },
    verificationPayload,
    fingerprintSource,
    verificationMaxAgeSeconds,
    requireSignedVerification,
    verificationTimestampValid,
    verificationFresh,
    verificationAgeSeconds,
    toolName,
    intent,
    message,
    arguments: argumentsSafe,
    suppliedIdempotencyKey: suppliedIdempotencyKey || null,
    idempotencyKey: suppliedIdempotencyKey || null,
    idempotencyKeyConflict,
    validationIssues,
    requiredIntegrationConfig,
    stableRequestIdentityAvailable: safeStableRequestIdentityAvailable,
    validationBaseOk: validationIssues.length === 0,
    customerIdentityPresent: identityPresent,
    customerIdentityStrongEnough: identityStrongEnough,
    customerIdentityTrust: sideEffectingIntent ? 'caller_provided' : (intent === 'get_order_status' ? 'verified_context_required' : 'caller_provided'),
    sideEffectingIntent,
    claimToken,
    isValid: false
  }
}];

const normalized = $('Normalize & Validate Request').first().json;
const raw = ($json && typeof $json === 'object') ? $json : {};
const ctx = { ...normalized, ...raw };

const issues = Array.isArray(normalized.validationIssues) ? [...normalized.validationIssues] : [];
const addIssue = (value) => { if (!issues.includes(value)) issues.push(value); };

const supplied = String(normalized.trustedVerification?.signature || '')
  .trim()
  .toLowerCase()
  .replace(/^sha256=/, '');
const computed = String(raw.computedVerificationSignature || '')
  .trim()
  .toLowerCase();

const constantTimeEqual = (a, b) => {
  const aa = String(a);
  const bb = String(b);
  let diff = aa.length ^ bb.length;
  const limit = Math.max(aa.length, bb.length);
  for (let i = 0; i < limit; i++) {
    const ca = i < aa.length ? aa.charCodeAt(i) : 0;
    const cb = i < bb.length ? bb.charCodeAt(i) : 0;
    diff |= (ca ^ cb);
  }
  return diff === 0;
};

let verificationState = 'not_required';

if (normalized.intent === 'get_order_status') {
  if (!normalized.trustedVerification?.reference) {
    verificationState = 'missing_reference';
  } else if (normalized.trustedVerification?.status !== 'verified') {
    verificationState = 'unverified';
  } else if (!normalized.verificationTimestampValid) {
    verificationState = 'invalid_timestamp';
  } else if (normalized.verificationAgeSeconds < 0) {
    verificationState = 'future_timestamp';
  } else if (normalized.verificationAgeSeconds > normalized.verificationMaxAgeSeconds) {
    verificationState = 'expired';
  } else if (!supplied) {
    verificationState = 'missing_signature';
  } else if (!computed || !constantTimeEqual(supplied, computed)) {
    verificationState = 'invalid_signature';
  } else {
    verificationState = 'verified';
  }

  if (verificationState !== 'verified') {
    addIssue('secure customer verification');
  }
}

const requestFingerprint = computed ? `fp-${computed}` : null;

const sideEffectingIntent = ['book_appointment','create_support_ticket','escalate_to_human'].includes(normalized.intent);
let idempotencyKey = normalized.idempotencyKey;
if (!idempotencyKey) {
  if (normalized.provider && normalized.callId && normalized.toolCallId) {
    idempotencyKey = `${normalized.provider}:${normalized.callId}:${normalized.toolCallId}`;
  } else if (!sideEffectingIntent && normalized.provider && normalized.toolCallId) {
    idempotencyKey = `${normalized.provider}:tool:${normalized.toolCallId}`;
  } else if (!sideEffectingIntent && normalized.provider && normalized.requestIdSupplied && normalized.requestId) {
    idempotencyKey = `${normalized.provider}:request:${normalized.requestId}`;
  }
}

if (!idempotencyKey || (sideEffectingIntent && !(normalized.idempotencyKey || (normalized.provider && normalized.callId && normalized.toolCallId)))) {
  addIssue('idempotency key or stable request identity');
}

const securityValid =
  normalized.intent !== 'get_order_status' ||
  verificationState === 'verified';

const validationBaseOk = issues.length === 0;
const isValid = validationBaseOk && securityValid && !!requestFingerprint && !!idempotencyKey;

return [{
  json: {
    ...ctx,
    trustedVerification: {
      ...normalized.trustedVerification,
      state: verificationState
    },
    verificationState,
    securityValid,
    orderAccessAuthorized: normalized.intent === 'get_order_status' ? verificationState === 'verified' : false,
    computedRequestFingerprint: raw.computedRequestFingerprint || null,
    requestFingerprint,
    idempotencyKey,
    sideEffectingIntent,
    validationIssues: issues,
    validationBaseOk,
    isValid
  }
}];

const normalized = $('Normalize & Validate Request').first().json;
let ctx = normalized;
try {
  ctx = { ...normalized, ...$('Finalize Security & Request Identity').first().json };
} catch {}

const raw = ($json && typeof $json === 'object') ? $json : {};

const baseResponse = (overrides) => ({
  schemaVersion: '1.0',
  success: false,
  requestId: ctx.requestId || null,
  sessionId: ctx.sessionId || null,
  callId: ctx.callId || null,
  toolCallId: ctx.toolCallId || null,
  provider: ctx.provider || 'unknown',
  intent: ctx.intent || 'unknown',
  action: 'validate_request',
  message: 'I could not safely validate this request.',
  data: {},
  escalationRequired: false,
  escalationCreated: false,
  escalationId: null,
  ticketId: null,
  retryable: false,
  errorCode: 'INVALID_REQUEST',
  timestamp: ctx.timestamp || new Date().toISOString(),
  verificationState: ctx.verificationState || 'not_required',
  idempotencyState: 'not_claimed',
  consistencyState: 'confirmed',
  upstreamStatusCode: null,
  httpStatus: 400,
  ...overrides
});

if (raw.error || raw.errorMessage) {
  const response = {
    ...baseResponse({
      action: 'verification_context_check',
      message: 'I could not validate the secure verification context for this request. Please try again later.',
      retryable: true,
      errorCode: 'VERIFICATION_BACKEND_UNAVAILABLE',
      verificationState: 'verification_backend_unavailable',
      httpStatus: 503
    })
  };

  return [{
    json: {
      ...ctx,
      trustedVerification: {
        ...(ctx.trustedVerification || {}),
        state: 'verification_backend_unavailable'
      },
      verificationState: 'verification_backend_unavailable',
      actionResult: { ...response, responseHttpStatus: 503 },
      response,
      responseHttpStatus: 503,
      responseOverride: response,
      persistencePayload: {
        idempotencyKey: null,
        ownerToken: null,
        requestFingerprint: ctx.requestFingerprint || null,
        shouldPersist: false,
        response
      },
      logRecord: {
        requestId: response.requestId,
        sessionId: response.sessionId,
        callId: response.callId,
        toolCallId: response.toolCallId,
        provider: response.provider,
        channel: ctx.channel || 'voice',
        intent: response.intent,
        action: response.action,
        success: false,
        errorCode: response.errorCode,
        escalationRequired: false,
        escalationCreated: false,
        timestamp: response.timestamp,
        messageLength: response.message.length,
        idempotencyState: 'not_claimed',
        consistencyState: 'confirmed'
      }
    }
  }];
}

const issues = Array.isArray(ctx.validationIssues) ? [...new Set(ctx.validationIssues)] : [];

const friendly = {
  sessionId: 'session information',
  toolName: 'support action',
  message: 'your message',
  'customer identity': 'customer identity',
  'customer phone or email': 'a verified phone number or email address',
  'arguments.orderId': 'your order ID',
  'secure customer verification': 'secure customer verification',
  'verification signature': 'a valid verification signature',
  'verification freshness': 'fresh customer verification',
  'arguments.preferredDate': 'your preferred appointment date',
  'arguments.preferredTime': 'your preferred appointment time',
  'arguments.timezone': 'your appointment timezone',
  'issue or message': 'your support issue',
  'reason or message': 'the reason for escalation',
  'timestamp invalid': 'a valid request timestamp',
  'timestamp too_old': 'a fresh request timestamp',
  'timestamp in_future': 'a valid request timestamp',
  'idempotency key conflict': 'a single consistent idempotency key',
  'integration configuration': 'required service configuration',
  'idempotency key or stable request identity': 'a stable request identity or idempotency key'
};

let errorCode = 'INVALID_REQUEST';
let message = 'I could not safely validate this request.';
let httpStatus = 400;
let retryable = false;

if (Array.isArray(ctx.requiredIntegrationConfig) && ctx.requiredIntegrationConfig.length) {
  errorCode = 'INTEGRATION_CONFIGURATION_ERROR';
  message = 'This support action is temporarily unavailable because a required service configuration is missing.';
  httpStatus = 503;
  retryable = false;
}

if (!(Array.isArray(ctx.requiredIntegrationConfig) && ctx.requiredIntegrationConfig.length)) switch (ctx.verificationState) {
  case 'missing_reference':
    errorCode = 'VERIFICATION_REFERENCE_REQUIRED';
    message = 'I need a valid secure customer verification reference before I can provide order information.';
    httpStatus = 403;
    break;
  case 'missing_signature':
    errorCode = 'VERIFICATION_SIGNATURE_REQUIRED';
    message = 'I need a valid secure customer verification signature before I can provide order information.';
    httpStatus = 403;
    break;
  case 'invalid_signature':
    errorCode = 'INVALID_VERIFICATION_SIGNATURE';
    message = 'The customer verification could not be validated. Please verify your identity and try again.';
    httpStatus = 403;
    break;
  case 'expired':
    errorCode = 'VERIFICATION_EXPIRED';
    message = 'The customer verification has expired. Please complete verification again.';
    httpStatus = 403;
    break;
  case 'future_timestamp':
    errorCode = 'INVALID_VERIFICATION_TIMESTAMP';
    message = 'The customer verification timestamp is not valid. Please retry verification.';
    httpStatus = 403;
    break;
  case 'invalid_timestamp':
    errorCode = 'INVALID_VERIFICATION_TIMESTAMP';
    message = 'The customer verification timestamp is not valid. Please retry verification.';
    httpStatus = 403;
    break;
  case 'unverified':
    errorCode = 'VERIFICATION_REQUIRED';
    message = 'I need secure customer verification before I can provide order information.';
    httpStatus = 403;
    break;
}

const readable = issues
  .map((x) => friendly[x] || x)
  .slice(0, 5);

if (httpStatus === 400 && readable.length) {
  message = `I need a few details before I can safely process this request: ${readable.join(', ')}.`;
} else if (Array.isArray(ctx.requiredIntegrationConfig) && ctx.requiredIntegrationConfig.length) {
  errorCode = 'INTEGRATION_CONFIGURATION_ERROR';
  httpStatus = 503;
  retryable = false;
  message = 'This support action is temporarily unavailable because a required service configuration is missing.';
}

const response = baseResponse({
  message,
  data: { missingFields: readable, verificationState: ctx.verificationState || 'not_required' },
  retryable,
  errorCode,
  httpStatus
});

return [{
  json: {
    ...ctx,
    actionResult: { ...response, responseHttpStatus: httpStatus },
    response,
    responseHttpStatus: httpStatus,
    responseOverride: response,
    persistencePayload: {
      idempotencyKey: null,
      ownerToken: null,
      requestFingerprint: ctx.requestFingerprint || null,
      shouldPersist: false,
      response
    },
    logRecord: {
      requestId: response.requestId,
      sessionId: response.sessionId,
      callId: response.callId,
      toolCallId: response.toolCallId,
      provider: response.provider,
      channel: ctx.channel || 'voice',
      intent: response.intent,
      action: response.action,
      success: false,
      errorCode: response.errorCode,
      escalationRequired: false,
      escalationCreated: false,
      timestamp: response.timestamp,
      messageLength: response.message.length,
      idempotencyState: 'not_claimed',
      consistencyState: 'confirmed'
    }
  }
}];

const ctx = $('Finalize Security & Request Identity').first().json;
const raw = ($json && typeof $json === 'object') ? $json : {};

if (raw.error || raw.errorMessage) {
  return [{ json: { ...ctx, idempotencyState: 'error', idempotencyErrorCode: 'IDEMPOTENCY_BACKEND_FAILURE' } }];
}

const state = String(raw.claim_state || raw.claimState || '').toLowerCase();

if (['new','reclaimed','reclaimed_retryable','reclaimed_side_effect','active','stale','key_reuse','error'].includes(state)) {
  return [{
    json: {
      ...ctx,
      idempotencyState: state,
      storedResponse: null,
      duplicateStatus: state.toUpperCase()
    }
  }];
}

let storedResponse = raw.response_json ?? raw.responseJson ?? null;
if (typeof storedResponse === 'string') {
  try { storedResponse = JSON.parse(storedResponse); } catch { storedResponse = null; }
}

let storedFingerprint = null;
if (storedResponse && typeof storedResponse === 'object') {
  storedFingerprint =
    (typeof storedResponse._requestFingerprint === 'string' ? storedResponse._requestFingerprint : null);

  if (storedResponse.response && typeof storedResponse.response === 'object') {
    storedResponse = storedResponse.response;
  }
}

if (state === 'retryable_error') {
  return [{
    json: {
      ...ctx,
      idempotencyState: 'error',
      idempotencyErrorCode: 'RETRYABLE_ERROR_NOT_RECLAIMED'
    }
  }];
}

if (state === 'done') {
  return [{
    json: {
      ...ctx,
      idempotencyState: 'duplicate_done',
      storedResponse: (storedResponse && typeof storedResponse === 'object') ? storedResponse : null,
      storedFingerprint,
      duplicateStatus: 'DONE'
    }
  }];
}

return [{
  json: {
    ...ctx,
    idempotencyState: 'error',
    idempotencyErrorCode: 'IDEMPOTENCY_STATE_UNKNOWN'
  }
}];

const ctx = $('Finalize Security & Request Identity').first().json;
const state = $json.idempotencyState;
const stored = $json.storedResponse;
const storedFingerprint = $json.storedFingerprint || null;

const makeResponse = (overrides) => ({
  schemaVersion: '1.0',
  success: false,
  requestId: ctx.requestId || null,
  sessionId: ctx.sessionId || null,
  callId: ctx.callId || null,
  toolCallId: ctx.toolCallId || null,
  provider: ctx.provider || 'unknown',
  intent: ctx.intent || 'unknown',
  action: 'idempotency_check',
  message: 'I could not safely process this request.',
  data: {},
  escalationRequired: false,
  escalationCreated: false,
  escalationId: null,
  ticketId: null,
