  idempotencyState: state || 'unknown',
  consistencyState: 'confirmed',
  upstreamStatusCode: null,
  httpStatus: 500,
  ...overrides
});

if (state === 'duplicate_done') {
  if (!storedFingerprint || !ctx.requestFingerprint) {
    const response = makeResponse({
      action: 'idempotency_metadata_check',
      message: 'This request was completed, but its replay metadata is incomplete. Please contact human support rather than repeating the action.',
      retryable: false,
      errorCode: 'IDEMPOTENCY_METADATA_MISSING',
      consistencyState: 'uncertain',
      httpStatus: 503
    });
    return [{ json: { ...ctx, response, actionResult: { ...response, responseHttpStatus: 503 }, responseHttpStatus: 503, responseOverride: response,
      persistencePayload: { idempotencyKey: ctx.idempotencyKey, ownerToken: null, requestFingerprint: ctx.requestFingerprint, shouldPersist: false, response } } }];
  }

  if (storedFingerprint !== ctx.requestFingerprint) {
    const response = makeResponse({
      action: 'idempotency_key_reuse',
      message: 'This request identifier is already associated with a different request. Please start a new support request.',
      retryable: false,
      errorCode: 'IDEMPOTENCY_KEY_REUSE',
      httpStatus: 409
    });
    return [{ json: { ...ctx, response, actionResult: { ...response, responseHttpStatus: 409 }, responseHttpStatus: 409, responseOverride: response,
