  }

  if (stored && typeof stored === 'object' && stored.schemaVersion) {
    if (stored.retryable === true || String(stored.consistencyState || '').toLowerCase() === 'retryable') {
      const response = makeResponse({
        action: 'idempotency_stored_retryable_result',
        message: 'The stored result for this request is non-terminal and cannot be replayed as completed. Please retry using the same idempotency key or contact human support.',
