    return [{ json: { ...ctx, response, actionResult: { ...response, responseHttpStatus: httpStatus }, responseHttpStatus: httpStatus,
      responseOverride: response, persistencePayload: { idempotencyKey: ctx.idempotencyKey, ownerToken: null, requestFingerprint: ctx.requestFingerprint, shouldPersist: false, response } } }];
  }

  const response = makeResponse({
    action: 'idempotency_replay',
    message: 'This request was already completed, but the stored result is unavailable. Please contact human support.',
    escalationRequired: true,
    retryable: false,
    errorCode: 'IDEMPOTENCY_RESULT_MISSING',
    consistencyState: 'uncertain',
    httpStatus: 503
  });
  return [{ json: { ...ctx, response, actionResult: { ...response, responseHttpStatus: 503 }, responseHttpStatus: 503, responseOverride: response,
    persistencePayload: { idempotencyKey: ctx.idempotencyKey, ownerToken: null, requestFingerprint: ctx.requestFingerprint, shouldPersist: false, response } } }];
}

if (state === 'key_reuse') {
  const response = makeResponse({
    action: 'idempotency_key_reuse',
    message: 'This idempotency key is already associated with a different request. Please start a new support request.',
    retryable: false,
    errorCode: 'IDEMPOTENCY_KEY_REUSE',
    httpStatus: 409
  });
  return [{ json: { ...ctx, response, actionResult: { ...response, responseHttpStatus: 409 }, responseHttpStatus: 409, responseOverride: response,
    persistencePayload: { idempotencyKey: ctx.idempotencyKey, ownerToken: null, requestFingerprint: ctx.requestFingerprint, shouldPersist: false, response } } }];
}

if (state === 'stale') {
  const response = makeResponse({
    action: 'idempotency_stale_request',
    message: 'That request is no longer actively running, but it cannot be safely reclaimed automatically because it may contain a side effect. Please retry later using the same idempotency key so the result can be reconciled safely.',
    retryable: true,
    errorCode: 'STALE_REQUEST_NOT_RECLAIMED',
    httpStatus: 409
  });
  return [{ json: { ...ctx, response, actionResult: { ...response, responseHttpStatus: 409 }, responseHttpStatus: 409, responseOverride: response,
    persistencePayload: { idempotencyKey: ctx.idempotencyKey, ownerToken: null, requestFingerprint: ctx.requestFingerprint, shouldPersist: false, response } } }];
}

if (state === 'active') {
  const response = makeResponse({
    action: 'idempotency_check',
    message: 'That request is already being processed. Please retry shortly using the same idempotency key.',
    retryable: true,
    errorCode: 'REQUEST_IN_PROGRESS',
    httpStatus: 409
  });
  return [{ json: { ...ctx, response, actionResult: { ...response, responseHttpStatus: 409 }, responseHttpStatus: 409, responseOverride: response,
    persistencePayload: { idempotencyKey: ctx.idempotencyKey, ownerToken: null, requestFingerprint: ctx.requestFingerprint, shouldPersist: false, response } } }];
}

const response = makeResponse({
  action: 'idempotency_check',
