const ctx = $('Finalize Security & Request Identity').first().json;
const raw = ($json && typeof $json === 'object') ? $json : {};
const state = String(raw.reconciliation_state || raw.reconciliationState || '').toUpperCase();

const base = {
  schemaVersion: '1.0',
  success: false,
  requestId: ctx.requestId || null,
  sessionId: ctx.sessionId || null,
  callId: ctx.callId || null,
  toolCallId: ctx.toolCallId || null,
  provider: ctx.provider || 'unknown',
  intent: ctx.intent || 'unknown',
  action: 'stale_side_effect_reconciliation',
  message: 'I could not safely determine whether the earlier external action completed. Do not create it again; use the same idempotency key for follow-up reconciliation.',
  data: { reconciliationIdempotencyKey: ctx.idempotencyKey || null },
  escalationRequired: true,
  escalationCreated: false,
  escalationId: null,
  ticketId: null,
  retryable: true,
  errorCode: 'STALE_SIDE_EFFECT_REQUIRES_RECONCILIATION',
  timestamp: ctx.timestamp || new Date().toISOString(),
  verificationState: ctx.verificationState || 'not_required',
  idempotencyState: 'stale',
  consistencyState: 'uncertain',
  upstreamStatusCode: null,
  httpStatus: 409
};

let evidence = raw.evidence_response_json ?? raw.evidenceResponseJson ?? null;
if (typeof evidence === 'string') {
  try { evidence = JSON.parse(evidence); } catch { evidence = null; }
}
if (evidence?.response && typeof evidence.response === 'object') evidence = evidence.response;

let response = base;

if (raw.error || raw.errorMessage) {
  response = {
    ...base,
    action: 'stale_side_effect_reconciliation',
    message: 'I could not safely check the stored evidence for that earlier external action. Do not create it again; use the same idempotency key for reconciliation.',
    errorCode: 'STALE_RECONCILIATION_BACKEND_FAILURE',
    httpStatus: 503,
    consistencyState: 'uncertain'
  };
} else if (state === 'RECONCILED' && evidence && typeof evidence === 'object' && evidence.schemaVersion) {
  response = {
    ...evidence,
    action: 'stale_reconciliation_replay',
    idempotencyState: 'duplicate_done',
    consistencyState: evidence.consistencyState || 'confirmed',
    data: {
      ...(evidence.data && typeof evidence.data === 'object' ? evidence.data : {}),
      reconciledFromStaleExecution: true
    },
    httpStatus: Number(evidence.httpStatus || 200)
  };
} else if (state === 'UNCERTAIN_EVIDENCE') {
  response = {
    ...base,
    action: 'stale_side_effect_reconciliation',
    message: 'The earlier execution left evidence that the external outcome cannot be established safely yet. Do not create the action again; use the same idempotency key for reconciliation.',
    errorCode: 'STALE_SIDE_EFFECT_OUTCOME_UNCERTAIN',
    data: {
      reconciliationIdempotencyKey: ctx.idempotencyKey || null,
      storedEvidence: evidence?.data && typeof evidence.data === 'object' ? evidence.data : {}
    },
    httpStatus: 503
  };
} else if (state === 'OWNER_RECLAIM_FAILED' || state === 'NOT_FOUND_OR_OWNER_CHANGED') {
  response = {
    ...base,
    action: 'stale_side_effect_reconciliation',
    message: 'The earlier execution is no longer owned by this request, and the external outcome could not be safely established. Do not create the action again; use the same idempotency key for reconciliation.',
    errorCode: 'STALE_SIDE_EFFECT_OWNER_CHANGED',
    httpStatus: 503,
    consistencyState: 'uncertain'
  };
}

const logRecord = {
  requestId: response.requestId,
  sessionId: response.sessionId,
  callId: response.callId,
  toolCallId: response.toolCallId,
  provider: response.provider,
  channel: ctx.channel || 'voice',
  intent: response.intent,
  action: response.action,
  success: response.success === true,
  errorCode: response.errorCode,
  escalationRequired: response.escalationRequired === true,
  escalationCreated: response.escalationCreated === true,
  timestamp: response.timestamp,
  messageLength: String(response.message || '').length,
  idempotencyState: response.idempotencyState,
  consistencyState: response.consistencyState
};

return [{
  json: {
    ...ctx,
    response,
    responseOverride: response,
    responseHttpStatus: response.httpStatus,
    logRecord,
    persistencePayload: {
      idempotencyKey: ctx.idempotencyKey,
      ownerToken: null,
      requestFingerprint: ctx.requestFingerprint,
      shouldPersist: false,
      response
    }
  }
}];

const normalized = $('Normalize & Validate Request').first().json;
let ctx = normalized;
try { ctx = { ...normalized, ...$('Finalize Security & Request Identity').first().json }; } catch {}

let finalState = null;
try {
  const f = $('Build Final Response & Log').first().json;
  finalState = (f && typeof f === 'object') ? f : null;
} catch {}

const response = finalState?.response;
const persistenceAttempted = !!finalState?.persistencePayload?.shouldPersist;

if (response && persistenceAttempted) {
  const sideEffecting = ['book_appointment','create_support_ticket','escalate_to_human'].includes(response.intent);

  if (sideEffecting) {
    const uncertain = {
      ...response,
      success: false,
      action: 'result_persistence_uncertain',
      message: 'I could not safely confirm the durable final status of that request. The external action may already have happened, so do not create it again. Use the same idempotency key for reconciliation or contact human support.',
      data: { reconciliationIdempotencyKey: ctx.idempotencyKey || null },
      escalationRequired: response.escalationRequired === true,
      escalationCreated: response.escalationCreated === true,
      escalationId: response.escalationId ?? null,
      ticketId: response.ticketId ?? null,
      retryable: true,
      errorCode: 'RESULT_PERSISTENCE_UNCERTAIN',
      httpStatus: 503,
      consistencyState: 'uncertain',
      idempotencyState: ctx.idempotencyState || 'new',
      upstreamStatusCode: response.upstreamStatusCode ?? null,
      data: {
        ...(response.data && typeof response.data === 'object' ? response.data : {}),
        reconciliationIdempotencyKey: ctx.idempotencyKey || null,
        originalOutcome: {
          success: response.success === true,
          action: response.action || null
        }
      }
    };

    return [{
      json: {
        ...ctx,
        actionResult: { ...uncertain, responseHttpStatus: 503 },
        response: uncertain,
        responseOverride: uncertain,
        responseHttpStatus: 503,
        consistencyState: 'uncertain',
        persistenceError: true,
        logRecord: {
          requestId: uncertain.requestId,
          sessionId: uncertain.sessionId,
          callId: uncertain.callId,
          toolCallId: uncertain.toolCallId,
          provider: uncertain.provider,
          channel: ctx.channel || 'voice',
          intent: uncertain.intent,
          action: uncertain.action,
          success: false,
          errorCode: uncertain.errorCode,
          escalationRequired: true,
          escalationCreated: false,
          timestamp: uncertain.timestamp,
          messageLength: uncertain.message.length,
          idempotencyState: uncertain.idempotencyState,
          consistencyState: 'uncertain'
        }
      }
    }];
  }

  return [{
    json: {
      ...ctx,
      actionResult: { ...finalState.actionResult, responseHttpStatus: finalState.responseHttpStatus },
      response,
      responseOverride: response,
      responseHttpStatus: finalState.responseHttpStatus || response.httpStatus || 200,
      consistencyState: response.consistencyState || 'confirmed',
      persistenceError: true,
      logRecord: finalState.logRecord
    }
  }];
}

const infra = {
  schemaVersion: '1.0',
  success: false,
  requestId: ctx.requestId || null,
  sessionId: ctx.sessionId || null,
  callId: ctx.callId || null,
  toolCallId: ctx.toolCallId || null,
  provider: ctx.provider || 'unknown',
  intent: ctx.intent || 'unknown',
  action: 'idempotency_check',
  message: 'I could not safely start this request because request-deduplication storage is unavailable. Please try again.',
  data: {},
  escalationRequired: false,
  escalationCreated: false,
  escalationId: null,
  ticketId: null,
  retryable: true,
  errorCode: 'IDEMPOTENCY_BACKEND_FAILURE',
  timestamp: ctx.timestamp || new Date().toISOString(),
  verificationState: ctx.verificationState || 'not_required',
  idempotencyState: 'error',
  consistencyState: 'confirmed',
  upstreamStatusCode: null,
  httpStatus: 503
};

return [{
  json: {
    ...ctx,
    actionResult: { ...infra, responseHttpStatus: 503 },
    response: infra,
    responseOverride: infra,
    responseHttpStatus: 503,
    persistencePayload: {
      idempotencyKey: null,
      ownerToken: null,
      requestFingerprint: ctx.requestFingerprint || null,
      shouldPersist: false,
      response: infra
    },
    logRecord: {
      requestId: infra.requestId,
      sessionId: infra.sessionId,
