}];

const ctx = $('Finalize Security & Request Identity').first().json;
const raw = ($json && typeof $json === 'object') ? $json : {};
let payload = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const statusCode = Number(raw.statusCode || payload.statusCode || 200);
if (raw.error || raw.errorMessage || statusCode >= 500) {
  return [{
    json: {
      ...ctx,
      knowledgeFound: false,
      kbFailure: true,
      verifiedKnowledge: []
    }
  }];
}

if (statusCode >= 400) {
  return [{
    json: {
      ...ctx,
      knowledgeFound: false,
      kbFailure: true,
      verifiedKnowledge: []
    }
  }];
}

const candidates = Array.isArray(payload.results)
  ? payload.results
  : (Array.isArray(payload.documents) ? payload.documents : []);

const sourceVerified = payload.sourceVerified === true;
const verified = candidates.map((item) => {
  const obj = (item && typeof item === 'object') ? item : { content: String(item ?? '') };
  const content = typeof obj.content === 'string' ? obj.content
    : (typeof obj.text === 'string' ? obj.text : '');
  return {
    verified: sourceVerified || obj.verified === true,
    content: content.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim().slice(0, 2500),
    sourceId: typeof obj.sourceId === 'string' ? obj.sourceId.slice(0, 150) : null
  };
}).filter((item) => item.verified && item.content);

return [{
  json: {
    ...ctx,
    knowledgeFound: verified.length > 0,
    kbFailure: false,
    verifiedKnowledge: verified.slice(0, 5)
  }
}];

