parameters.jsCode:
const raw = ($json && typeof $json === 'object') ? $json : {};
const parse = (v) => {
  if (v && typeof v === 'object') return v;
  if (typeof v !== 'string' || !v.trim()) return {};
  try {
    const p = JSON.parse(v);
    return (p && typeof p === 'object') ? p : {};
  } catch {
    return {};
  }
};
const body = parse(raw.body && typeof raw.body === 'object' ? raw.body : raw);
const answer = String(
  body?.choices?.[0]?.message?.content ??
  body?.output?.text ??
  body?.message?.content ??
  (typeof body?.message === 'string' ? body.message : '')
).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim().slice(0, 1200);

const suspicious = [
  /(?:api[_ -]?key|secret|password|authorization|bearer|access[_ -]?token|credential)\s*[:=]/i,
  /ignore (?:all|any|the) (?:previous|prior|system|developer) instructions/i,
  /<\s*(?:system|developer)\s*>/i,
  /\b(?:system prompt|developer message|internal architecture|private credentials)\b/i
];

const refusal = /(?:i (?:can't|cannot|do not have enough information)|i'm unable to verify|please contact human support|human support can help)/i;

let verifiedKnowledge = [];
try {
  verifiedKnowledge = $('Prepare Verified Knowledge').first().json.verifiedKnowledge;
} catch {}
if (!Array.isArray(verifiedKnowledge)) verifiedKnowledge = [];

const sourceText = verifiedKnowledge
  .map((x) => String(x?.content || ''))
  .filter(Boolean)
  .join('\n')
  .slice(0, 12000);

const normalizeToken = (t) => t
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '')
  .trim();

const sourceTokens = new Set(
  sourceText.split(/\s+/)
    .map(normalizeToken)
    .filter((t) => t.length >= 4)
);

const answerTokens = Array.from(new Set(
  answer.split(/\s+/)
    .map(normalizeToken)
    .filter((t) => t.length >= 4)
));

const overlapCount = answerTokens.filter((t) => sourceTokens.has(t)).length;

const highRiskClaim = /(?:\b(?:price|cost|refund|refunds|delivery|deliver|days?|hours?|policy|policies|fee|fees|charge|charges|eligible|eligibility|warranty|cancel|cancellation|subscription|discount)\b|[$€£৳]\s*\d|\b\d+(?:\.\d+)?\s*(?:USD|EUR|GBP|BDT)\b|\b20\d{2}[-/]\d{1,2}[-/]\d{1,2}\b)/i;

const numericFacts = (answer.match(/[$€£৳]\s*\d+(?:[.,]\d+)?|\b\d+(?:\.\d+)?\s*(?:USD|EUR|GBP|BDT)?\b|\b20\d{2}[-/]\d{1,2}[-/]\d{1,2}\b/g) || [])
  .map((x) => x.replace(/\s+/g, ' ').trim().toLowerCase());

let unsupportedNumericFact = false;
for (const fact of numericFacts) {
  if (!sourceText.toLowerCase().includes(fact)) {
    unsupportedNumericFact = true;
    break;
  }
}

let aiValidationFailure = null;
if (!answer) {
  aiValidationFailure = 'AI_RESPONSE_EMPTY';
} else if (suspicious.some((rx) => rx.test(answer))) {
  aiValidationFailure = 'AI_RESPONSE_UNSAFE_CONTENT';
} else if (highRiskClaim.test(answer) && sourceText && (overlapCount < 2 || unsupportedNumericFact)) {
  aiValidationFailure = unsupportedNumericFact
    ? 'AI_RESPONSE_UNSUPPORTED_FACT'
    : 'AI_RESPONSE_UNGROUNDED_CLAIM';
} else if (!refusal && sourceText && overlapCount === 0) {
  aiValidationFailure = 'AI_RESPONSE_UNGROUNDED';
} else if (!refusal && !sourceText) {
  aiValidationFailure = 'AI_RESPONSE_NO_VERIFIED_SOURCE';
}

return [{
  json: {
    ...raw,
    aiValidatedAnswer: answer || null,
    aiValidationFailure
  }
}];

