let base = normalized;
try {
  base = { ...normalized, ...$('Finalize Security & Request Identity').first().json };
} catch {}
const sideEffecting = ['book_appointment','create_support_ticket','escalate_to_human'].includes(base.intent);
const response = {
  schemaVersion: '1.0',
  success: false,
  requestId: base.requestId || null,
  sessionId: base.sessionId || null,
  callId: base.callId || null,
  toolCallId: base.toolCallId || null,
  provider: base.provider || 'unknown',
  intent: base.intent || 'unknown',
  action: sideEffecting ? 'side_effect_outcome_uncertain' : 'response_processing_failure',
  message: sideEffecting
    ? 'I could not safely finalize the status of that request. The external action may already have happened, so do not create it again. Use the same idempotency key for reconciliation.'
    : 'I could not safely finalize the request response. Please retry.',
  data: sideEffecting ? { reconciliationIdempotencyKey: base.idempotencyKey || null } : {},
  escalationRequired: sideEffecting,
  escalationCreated: false,
  escalationId: null,
  ticketId: null,
  retryable: true,
  errorCode: sideEffecting ? 'RESULT_PROCESSING_UNCERTAIN' : 'RESPONSE_PROCESSING_FAILURE',
  timestamp: base.timestamp || new Date().toISOString(),
  verificationState: base.verificationState || 'not_required',
  idempotencyState: base.idempotencyState || 'not_claimed',
  consistencyState: sideEffecting ? 'uncertain' : 'confirmed',
  upstreamStatusCode: null,
  httpStatus: 503
};
const logRecord = {
  requestId: response.requestId, sessionId: response.sessionId, callId: response.callId,
  toolCallId: response.toolCallId, provider: response.provider, channel: 'voice',
  intent: response.intent, action: response.action, success: response.success === true,
  errorCode: response.errorCode, escalationRequired: response.escalationRequired === true,
  escalationCreated: response.escalationCreated === true, timestamp: response.timestamp,
  messageLength: response.message.length, idempotencyState: response.idempotencyState,
  consistencyState: response.consistencyState
};
return [{json: {response, responseHttpStatus: 503, responseOverride: response, logRecord}}];

const ctx = $('Finalize Security & Request Identity').first().json;
