let message = 'I could not safely confirm the durable evidence for that external action. The action may already have happened, so do not create it again. Use the same idempotency key for reconciliation.';
if (consistency === 'uncertain' && evidenceRecorded && !dbError) {
  errorCode = 'SIDE_EFFECT_OUTCOME_UNCERTAIN';
  message = 'I could not confirm the final outcome of the external action. Do not create it again. Use the same idempotency key for reconciliation.';
} else if (String(raw.evidence_state || '').toUpperCase() === 'OWNER_MISMATCH_OR_NOT_IN_PROGRESS') {
  errorCode = 'SIDE_EFFECT_EVIDENCE_OWNER_FENCE_LOST';
  message = 'The request ownership changed before the external action evidence could be durably recorded. The action may already have happened, so do not create it again. Use the same idempotency key for reconciliation.';
} else if (dbError) {
  errorCode = 'SIDE_EFFECT_EVIDENCE_PERSISTENCE_UNCERTAIN';
  message = 'I could not safely record the evidence for that external action. The action may already have happened, so do not create it again. Use the same idempotency key for reconciliation.';
