const response = {
  ...original,
  success: false,
  action: 'side_effect_evidence_uncertain',
  message,
  data: {
    ...(original.data && typeof original.data === 'object' ? original.data : {}),
    reconciliationIdempotencyKey: ctx.idempotencyKey || null,
    evidenceState: raw.evidence_state || (dbError ? 'DATABASE_ERROR' : 'UNKNOWN')
  },
  retryable: true,
  errorCode,
  consistencyState: 'uncertain',
  idempotencyState: ctx.idempotencyState || 'new',
  httpStatus: 503
};

