  timestamp: response.timestamp, messageLength: response.message.length,
  idempotencyState: response.idempotencyState, consistencyState: 'uncertain'
};

return [{
  json: {
    ...ctx,
    response,
    responseOverride: response,
    responseHttpStatus: 503,
    persistenceDecision: 'side_effect_uncertain',
    persistenceError: dbError,
    logRecord
  }
}];
